1	package remote
2	
3	import (
4		"context"
5		"encoding/base64"
6		"fmt"
7		"log/slog"
8		"os"
9		"os/exec"
10		"path/filepath"
11		"strconv"
12		"strings"
13		"sync"
14	
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16		"github.com/entireio/cli/cmd/entire/cli/settings"
17	)
18	
19	// CheckpointTokenEnvVar is the environment variable for providing an access token
20	// used to authenticate git push/fetch operations for checkpoint branches.
21	// The token is injected as an HTTP Basic Authorization header per RFC 7617:
22	// the credentials string "x-access-token:<token>" is base64-encoded and sent as
23	// "Authorization: Basic <base64>". This matches GitHub's token auth for Git HTTPS.
24	// SSH remotes ignore the token (with a warning).
25	const CheckpointTokenEnvVar = "ENTIRE_CHECKPOINT_TOKEN"
26	
27	var sshTokenWarningOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
28	
29	// FetchOptions configures a git fetch operation.
30	type FetchOptions struct {
31		Remote   string   // remote name or URL (required)
32		RefSpecs []string // one or more refspecs / object hashes
33		NoTags   bool     // adds --no-tags
34		NoFilter bool     // when true, skips --filter=blob:none even if filtered fetches are enabled
35		// Shallow adds --depth=1 to fetch only the tip commit and its tree. Use
36		// for tip-only probes (e.g. resolving the latest checkpoint metadata)
37		// where ancestry isn't needed. Creates .git/shallow state — callers that
38		// later require full history should opt into Unshallow on a follow-up
39		// fetch.
40		Shallow bool
41		// Unshallow adds --unshallow when the repository is currently shallow,
42		// triggering git to download the rest of the history for the fetched ref.
43		// Set this on metadata-repair / reconcile paths that need complete
44		// checkpoint ancestry. Do not set on generic branch fetches — it would
45		// silently convert a deliberately-shallow user clone into a full one.
46		Unshallow bool
47		// Depth adds --depth=<Depth>, fetching the refspec to this absolute depth.
48		// Unlike Unshallow (which is repo-global) this is ref-scoped: it fully
49		// fetches the named branch — healing a prior shallow boundary on it — while
50		// leaving an independently-shallow source-tree clone untouched, and it does
51		// not introduce shallowness on a full repo when the value exceeds the
52		// branch's length. Use a value above the branch's realistic length but below
53		// math.MaxInt32 (2147483647), which git special-cases as a global unshallow.
54		// Ignored when zero or when Shallow is set.
55		Depth     int
56		Dir       string   // working directory (empty = CWD)
57		ExtraArgs []string // additional flags before remote (e.g., "--no-write-fetch-head")
58	}
59	
60	// Fetch runs git fetch with checkpoint token injection and optional
61	// filtered fetches (--filter=blob:none when settings enable it).
62	// GIT_TERMINAL_PROMPT=0 is always set.
63	//
64	// Callers that pass a remote name (e.g., "origin") and want filtered fetches to
65	// resolve the name to a URL (to avoid persisting promisor settings) should call
66	// ResolveFetchTarget first and pass the resolved target as opts.Remote.
67	func Fetch(ctx context.Context, opts FetchOptions) ([]byte, error) {
68		args := []string{"fetch", "--no-auto-gc"}
69		if opts.NoTags {
70			args = append(args, "--no-tags")
71		}
72		args = append(args, opts.ExtraArgs...)
73		switch {
74		case opts.Shallow:
75			args = append(args, "--depth=1")
76		case opts.Depth > 0:
77			args = append(args, fmt.Sprintf("--depth=%d", opts.Depth))
78		case opts.Unshallow && isShallowRepository(ctx, opts.Dir):
79			args = append(args, "--unshallow")
80		}
81		filtered := !opts.NoFilter && settings.IsFilteredFetchesEnabled(ctx)
82		if filtered {
83			args = append(args, "--filter=blob:none")
84		}
85		args = append(args, opts.Remote)
86		args = append(args, opts.RefSpecs...)
87	
88		cmd := newCommand(ctx, args...)
89		if opts.Dir != "" {
90			cmd.Dir = opts.Dir
91		}
92		disableTerminalPrompt(cmd)
93		out, err := cmd.CombinedOutput()
94		if err != nil {
95			return out, fmt.Errorf("git fetch: %w", err)
96		}
97		if filtered && IsURL(opts.Remote) {
98			// Stamp the URL git actually fetched from: with a checkpoint token set,
99			// newCommand rewrites SSH targets to HTTPS, and git records the
100			// promisor entry under the rewritten URL.
101			target := opts.Remote
102			if token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)); token != "" && isValidToken(token) {
103				target, _ = resolveTargetForTokenAuth(ctx, target)
104			}
105			markPromisorEntrySkipped(ctx, opts.Dir, target)
106		}
107		return out, nil
108	}
109	
110	// markPromisorEntrySkipped excludes the URL-keyed config section that git
111	// creates for a filtered URL fetch (remote.<url>.promisor=true) from
112	// `git fetch --all` and `git remote update`. Git needs the promisor entry to
113	// lazy-fetch filtered-out objects later, but the entry also makes the URL show
114	// up as a fetchable remote, so without this every checkpoint URL ever fetched
115	// from lingers as a phantom remote that bulk fetches keep dialing.
116	// Best-effort: the fetch already succeeded, so failures only log.
117	func markPromisorEntrySkipped(ctx context.Context, dir, url string) {
118		if !gitConfigBool(ctx, dir, "remote."+url+".promisor") {
119			// Git didn't record a promisor entry for this URL; don't invent a
120			// config section that wouldn't otherwise exist.
121			return
122		}
123		for _, key := range []string{"skipFetchAll", "skipDefaultUpdate"} {
124			fullKey := "remote." + url + "." + key
125			if gitConfigBool(ctx, dir, fullKey) {
126				// Checked per key so a partially-stamped entry (e.g. an earlier
127				// run failing between the two writes) still gets completed.
128				continue
129			}
130			cmd := exec.CommandContext(ctx, "git", "config", "--local", fullKey, "true")
131			if dir != "" {
132				cmd.Dir = dir
133			}
134			if out, cfgErr := cmd.CombinedOutput(); cfgErr != nil {
135				redactedURL := RedactURL(url)
136				// The output can echo the key, which embeds the URL — and a URL
137				// can carry credentials. Redact before logging.
138				msg := strings.TrimSpace(strings.ReplaceAll(string(out), url, redactedURL))
139				logging.Warn(ctx, "failed to mark promisor config entry as skipped for bulk fetches",
140					slog.String("url", redactedURL),
141					slog.String("key", key),
142					slog.String("output", msg),
143					slog.String("error", cfgErr.Error()),
144				)
145				return
146			}
147		}
148	}
149	
150	// gitConfigBool reads a local git config key and reports whether it is set to
151	// a true value. Missing keys and read errors report false.
152	func gitConfigBool(ctx context.Context, dir, key string) bool {
153		cmd := exec.CommandContext(ctx, "git", "config", "--local", "--get", "--type=bool", key)
154		if dir != "" {
155			cmd.Dir = dir
156		}
157		out, err := cmd.Output()
158		if err != nil {
159			return false
160		}
161		return strings.TrimSpace(string(out)) == "true"
162	}
163	
164	// FetchBlobs fetches specific objects (typically blobs) by hash from a remote.
165	// Uses `git fetch-pack` rather than `git fetch` because the high-level
166	// porcelain enforces partial-clone integrity checks that reject blob-only
167	// responses with "did not send all necessary objects". Plumbing skips those
168	// checks — it just downloads the requested objects into .git/objects/pack
169	// and exits — which is exactly what we want when grabbing individual blobs
170	// by SHA. Works against GitHub for any reachable object, including blobs.
171	//
172	// The remote should be a URL (not a remote name) to avoid persisting promisor
173	// settings onto the named remote. Use FetchURL to obtain the URL.
174	func FetchBlobs(ctx context.Context, remote string, hashes []string) error {
175		args := []string{"fetch-pack", remote}
176		args = append(args, hashes...)
177	
178		cmd := newCommand(ctx, args...)
179		disableTerminalPrompt(cmd)
180		output, err := cmd.CombinedOutput()
181		if err != nil {
182			redactedURL := RedactURL(remote)
183			msg := strings.TrimSpace(strings.ReplaceAll(string(output), remote, redactedURL))
184			if msg != "" {
185				return fmt.Errorf("git fetch-pack from %s: %s: %w", redactedURL, msg, err)
186			}
187			return fmt.Errorf("git fetch-pack from %s: %w", redactedURL, err)
188		}
189		return nil
190	}
191	
192	// PushResult holds raw porcelain output from git push.
193	type PushResult struct {
194		Output string
195	}
196	
197	// PushOptions configures a git push operation.
198	type PushOptions struct {
199		Remote    string
200		RefSpecs  []string
201		ExtraArgs []string // additional flags before remote
202		Dir       string
203	}
204	
205	// Push runs git push --no-verify --porcelain with token injection.
206	// GIT_TERMINAL_PROMPT=0 is always set.
207	func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
208		return PushWithOptions(ctx, PushOptions{
209			Remote:   remote,
210			RefSpecs: []string{refSpec},
211		})
212	}
213	
214	// PushWithOptions runs git push --no-verify --porcelain with token injection.
215	// GIT_TERMINAL_PROMPT=0 is always set.
216	func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
217		pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
218		if err != nil {
219			return PushResult{}, fmt.Errorf("resolve push target: %w", err)
220		}
221	
222		args := []string{"push", "--no-verify", "--porcelain"}
223		args = append(args, opts.ExtraArgs...)
224		args = append(args, pushTarget)
225		args = append(args, opts.RefSpecs...)
226	
227		cmd := newCommand(ctx, args...)
228		if opts.Dir != "" {
229			cmd.Dir = opts.Dir
230		}
231		disableTerminalPrompt(cmd)
232		output, err := cmd.CombinedOutput()
233		if err != nil {
234			return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
235		}
236		return PushResult{Output: string(output)}, nil
237	}
238	
239	// LsRemoteInDir is like LsRemote but runs in a specific directory.
240	func LsRemoteInDir(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
241		return lsRemote(ctx, dir, remote, patterns...)
242	}
243	
244	func lsRemote(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
245		args := append([]string{"ls-remote", remote}, patterns...)
246		cmd := newCommand(ctx, args...)
247		if dir != "" {
248			cmd.Dir = dir
249		}
250		disableTerminalPrompt(cmd)
251		out, err := cmd.Output()
252		if err != nil {
253			return out, fmt.Errorf("git ls-remote: %w", err)
254		}
255		return out, nil
256	}
257	
258	// IsURL returns true if the target looks like a URL rather than a git remote name.
259	func IsURL(target string) bool {
260		return strings.Contains(target, "://") || strings.Contains(target, "@")
261	}
262	
263	// ResolveFetchTarget returns the git fetch target to use. When filtered
264	// fetches are enabled, configured remotes are resolved to their URL so git does
265	// not persist promisor settings onto the remote name.
266	func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
267		if IsURL(target) || isLocalPath(target) || !settings.IsFilteredFetchesEnabled(ctx) {
268			return target, nil
269		}
270		url, err := GetRemoteURL(ctx, target)
271		if err != nil {
272			return "", fmt.Errorf("get remote URL: %w", err)
273		}
274		return url, nil
275	}
276	
277	// isShallowRepository returns true when the git repository at dir is shallow.
278	// An empty dir inherits the parent process's working directory, matching the
279	// semantics callers use when invoking Fetch with empty FetchOptions.Dir.
280	func isShallowRepository(ctx context.Context, dir string) bool {
281		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--is-shallow-repository")
282		cmd.Dir = dir
283		disableTerminalPrompt(cmd)
284		out, err := cmd.Output()
285		if err != nil {
286			return false
287		}
288		return strings.TrimSpace(string(out)) == "true"
289	}
290	
291	// newCommand creates an exec.Cmd for a git operation that may need
292	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set:
293	//   - if the target in args is (or resolves to) an SSH remote, the target is
294	//     rewritten in the args to the equivalent HTTPS URL so git uses HTTP
295	//     transport and our injected Authorization header applies;
296	//   - a Basic auth token is then injected via GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/
297	//     GIT_CONFIG_VALUE_* environment variables.
298	//
299	// If rewriting fails (unparseable URL, missing owner/repo) the command runs
300	// unmodified and a one-shot warning is printed.
301	// For empty/unset tokens, the command is returned unmodified.
302	//
303	// The remote is extracted from args by skipping the git subcommand and any flags
304	// (arguments starting with "-"). For example, in
305	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
306	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
307		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
308	
309		mkCmd := func(finalArgs []string) *exec.Cmd {
310			c := exec.CommandContext(ctx, "git", finalArgs...)
311			c.Stdin = nil // Disconnect stdin to prevent hanging in hook context
312			terminateOnCancel(c)
313			return c
314		}
315	
316		if token == "" {
317			return mkCmd(args)
318		}
319	
320		if !isValidToken(token) {
321			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
322			return mkCmd(args)
323		}
324	
325		target := extractRemoteFromArgs(args)
326		if target == "" {
327			return mkCmd(args)
328		}
329	
330		newTarget, protocol := resolveTargetForTokenAuth(ctx, target)
331		if newTarget != target {
332			args = replaceFirstPositional(args, newTarget)
333		}
334	
335		cmd := mkCmd(args)
336	
337		switch protocol {
338		case ProtocolSSH:
339			sshTokenWarningOnce.Do(func() {
340				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
341			})
342			return cmd
343		case ProtocolHTTPS:
344			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
345			return cmd
346		default:
347			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
348			return cmd
349		}
350	}
351	
352	// resolveTargetForTokenAuth resolves a git target (remote name or URL) to its
353	// effective protocol, rewriting SSH targets to the equivalent HTTPS URL so
354	// token-based auth can be applied. Returns the (possibly rewritten) target and
355	// its final protocol. Protocol is "" when resolution fails (local path,
356	// nonexistent remote, unparseable URL).
357	//
358	// This is only meaningful when ENTIRE_CHECKPOINT_TOKEN is set; callers gate on
359	// that themselves.
360	func resolveTargetForTokenAuth(ctx context.Context, target string) (string, string) {
361		if target == "" || isLocalPath(target) {
362			return target, ""
363		}
364	
365		rawURL := target
366		if !IsURL(target) {
367			var err error
368			rawURL, err = GetRemoteURL(ctx, target)
369			if err != nil {
370				return target, ""
371			}
372		}
373	
374		info, err := ParseURL(rawURL)
375		if err != nil {
376			return target, ""
377		}
378	
379		if info.Protocol == ProtocolSSH {
380			if httpsURL, ok := deriveTokenOriginURL(rawURL); ok {
381				return httpsURL, ProtocolHTTPS
382			}
383			return target, ProtocolSSH
384		}
385	
386		return target, info.Protocol
387	}
388	
389	// replaceFirstPositional returns a copy of args with the first non-flag
390	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
391	// use this to rewrite a remote name/URL after resolution without mutating the
392	// original slice.
393	func replaceFirstPositional(args []string, newTarget string) []string {
394		out := make([]string, len(args))
395		copy(out, args)
396		for i := 1; i < len(out); i++ {
397			if !strings.HasPrefix(out[i], "-") {
398				out[i] = newTarget
399				return out
400			}
401		}
402		return out
403	}
404	
405	// extractRemoteFromArgs finds the remote URL or name from git command args.
406	// It skips the subcommand (first arg) and any flags (args starting with "-"),
407	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
408	func extractRemoteFromArgs(args []string) string {
409		if len(args) < 2 {
410			return ""
411		}
412		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
413		for _, arg := range args[1:] {
414			if !strings.HasPrefix(arg, "-") {
415				return arg
416			}
417		}
418		return ""
419	}
420	
421	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
422	// an Authorization header into git HTTP requests. The token is sent as a Basic
423	// credential with the format "x-access-token:<token>" (base64-encoded), which
424	// is compatible with GitHub's token authentication.
425	//
426	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
427	// http.extraHeader entry is appended at the next free index and
428	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
429	// config (e.g., safe.directory, custom CA settings) intact.
430	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
431		existingCount := 0
432		for _, e := range baseEnv {
433			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
434			if !ok {
435				continue
436			}
437			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
438				existingCount = n
439			}
440		}
441	
442		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
443		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
444		filtered := make([]string, 0, len(baseEnv)+3)
445		for _, e := range baseEnv {
446			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
447				continue
448			}
449			filtered = append(filtered, e)
450		}
451	
452		idx := existingCount
453		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
454		return append(filtered,
455			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
456			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
457			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
458		)
459	}
460	
461	// isValidToken returns false if the token contains control characters (bytes < 0x20
462	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
463	// embedded in the token value.
464	func isValidToken(token string) bool {
